params.spec:
{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "One hexagon per GCS bucket, coloured by the share of API requests that returned a non-OK response over the selected window. Buckets are ordered worst-first. A bucket is only coloured once it has at least 50 requests in the window: below that a single NOT_FOUND from a scanner reads as 100% errors, so low-traffic buckets stay grey. Hover for a sparkline of the error rate. Click to open the bucket detail dashboard or Discover.",
  "usermeta": {
    "x_gcs_hexmap": true
  },
  "padding": {
    "top": 10,
    "left": 10,
    "right": 10,
    "bottom": 15
  },
  "data": [
    {
      "name": "ts_probe",
      "url": {
        "%type%": "esql",
        "%context%": true,
        "%timefield%": "@timestamp",
        "query": "ROW round_key = CONCAT(TO_STRING(?_tstart), \"|\", TO_STRING(?_tend)), fetched_at = NOW()"
      }
    },
    {
      "name": "raw_traffic",
      "url": {
        "%type%": "esql",
        "%context%": true,
        "%timefield%": "@timestamp",
        "query": "TS metrics-gcp.cloudstorage.otel-default\n| WHERE @timestamp >= ?_tstart AND @timestamp <= ?_tend\n    AND resource.attributes.gcp.resource_type == \"gcs_bucket\"\n| STATS total_reqs = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)),\n        err_reqs = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE attributes.response_code != \"OK\",\n        svc_reqs = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE attributes.response_code IN (\"UNAVAILABLE\", \"INTERNAL\", \"DEADLINE_EXCEEDED\", \"ABORTED\", \"RESOURCE_EXHAUSTED\"),\n        stored_bytes = SUM(LAST_OVER_TIME(`metrics.storage.googleapis.com/storage/total_bytes`))\n    BY svc = resource.attributes.bucket_name,\n       loc = resource.attributes.location,\n       proj = resource.attributes.project_id\n| EVAL err_pct = CASE(total_reqs >= 50, COALESCE(err_reqs, 0) * 100.0 / total_reqs, NULL),\n       svc_pct = CASE(total_reqs >= 50, COALESCE(svc_reqs, 0) * 100.0 / total_reqs, NULL),\n       round_key = CONCAT(TO_STRING(?_tstart), \"|\", TO_STRING(?_tend)),\n       fetched_at = NOW()\n| KEEP svc, loc, proj, total_reqs, stored_bytes, err_pct, svc_pct, round_key, fetched_at\n| LIMIT 10000"
      }
    },
    {
      "name": "raw_all",
      "source": "raw_traffic",
      "transform": [
        {
          "type": "formula",
          "as": "name",
          "expr": "datum.svc"
        }
      ]
    },
    {
      "name": "ranked_err",
      "source": "raw_all",
      "transform": [
        {
          "type": "formula",
          "as": "sort_key",
          "expr": "datum.err_pct == null ? 1e12 : -datum.err_pct * 1000000"
        },
        {
          "type": "collect",
          "sort": {
            "field": [
              "sort_key",
              "svc"
            ],
            "order": [
              "ascending",
              "ascending"
            ]
          }
        },
        {
          "type": "window",
          "ops": [
            "row_number"
          ],
          "as": [
            "active_rank"
          ]
        }
      ]
    },
    {
      "name": "active",
      "values": [],
      "on": [
        {
          "trigger": "ts_round !== '' && active_round !== '' && active_round !== ts_round",
          "remove": "true"
        },
        {
          "trigger": "metric === 'errors' && len_raw > 0 && raw_round === ts_round && ts_round !== ''",
          "remove": "true",
          "insert": "data('ranked_err')"
        },
        {
          "trigger": "metric === 'svcfault' && len_raw > 0 && raw_round === ts_round && ts_round !== ''",
          "remove": "true",
          "insert": "data('ranked_svc')"
        }
      ]
    },
    {
      "name": "instances",
      "source": "active",
      "transform": [
        {
          "type": "formula",
          "as": "active_val",
          "expr": "metric === 'errors' ? datum.err_pct : datum.svc_pct"
        },
        {
          "type": "formula",
          "as": "index0",
          "expr": "datum.active_rank - 1"
        },
        {
          "type": "formula",
          "as": "col",
          "expr": "datum.index0 % gridCols"
        },
        {
          "type": "formula",
          "as": "row",
          "expr": "floor(datum.index0 / gridCols)"
        },
        {
          "type": "formula",
          "as": "x",
          "expr": "datum.col * gapX + (datum.row % 2 == 1 ? gapX / 2 : 0) + hexR + 5"
        },
        {
          "type": "formula",
          "as": "y",
          "expr": "datum.row * gapY + hexR + 5 + hexOffsetY"
        },
        {
          "type": "formula",
          "as": "hexSize",
          "expr": "hexR * hexR * 3.46"
        }
      ]
    },
    {
      "name": "err_counts",
      "source": "raw_all",
      "transform": [
        {
          "type": "formula",
          "as": "v",
          "expr": "datum.err_pct"
        },
        {
          "type": "formula",
          "as": "bucket",
          "expr": "datum.v == null ? 3 : (datum.v >= 5 ? 2 : datum.v >= 1 ? 1 : 0)"
        },
        {
          "type": "aggregate",
          "groupby": [
            "bucket"
          ],
          "ops": [
            "count"
          ],
          "as": [
            "count"
          ]
        }
      ]
    },
    {
      "name": "err_legend_stops",
      "values": [
        {
          "label": "\u2265 5%",
          "val": 5,
          "bucket": 2,
          "is_nodata": false
        },
        {
          "label": "1 \u2013 4%",
          "val": 1,
          "bucket": 1,
          "is_nodata": false
        },
        {
          "label": "< 1%",
          "val": 0,
          "bucket": 0,
          "is_nodata": false
        },
        {
          "label": "Low / no traffic",
          "val": null,
          "bucket": 3,
          "is_nodata": true
        }
      ],
      "transform": [
        {
          "type": "lookup",
          "from": "err_counts",
          "key": "bucket",
          "fields": [
            "bucket"
          ],
          "values": [
            "count"
          ],
          "as": [
            "count"
          ],
          "default": 0
        },
        {
          "type": "window",
          "ops": [
            "row_number"
          ],
          "as": [
            "idx"
          ]
        }
      ]
    },
    {
      "name": "spinner_dots",
      "values": [
        {
          "i": 0
        },
        {
          "i": 1
        },
        {
          "i": 2
        },
        {
          "i": 3
        },
        {
          "i": 4
        },
        {
          "i": 5
        },
        {
          "i": 6
        },
        {
          "i": 7
        }
      ]
    },
    {
      "name": "pills",
      "values": [
        {
          "id": "errors",
          "label": "Errors %",
          "group": "metric",
          "x": 75,
          "w": 68
        },
        {
          "id": "svcfault",
          "label": "GCS-side faults %",
          "group": "metric",
          "x": 149,
          "w": 116
        }
      ]
    },
    {
      "name": "menu_items_data",
      "values": [
        {
          "id": "details",
          "label": "1. View bucket detail",
          "idx": 0
        },
        {
          "id": "metrics",
          "label": "2. View metrics in Discover",
          "idx": 1
        }
      ]
    },
    {
      "name": "menu_visible",
      "values": [
        {
          "_": 0
        }
      ],
      "transform": [
        {
          "type": "filter",
          "expr": "selected_instance != null"
        }
      ]
    },
    {
      "name": "menu_items_visible",
      "source": "menu_items_data",
      "transform": [
        {
          "type": "filter",
          "expr": "selected_instance != null"
        }
      ]
    },
    {
      "name": "spark_raw_traffic",
      "url": {
        "%type%": "esql",
        "%context%": true,
        "%timefield%": "@timestamp",
        "query": "FROM metrics-gcp.cloudstorage.otel-default\n| WHERE @timestamp >= ?_tstart AND @timestamp <= ?_tend\n    AND resource.attributes.gcp.resource_type == \"gcs_bucket\"\n    AND `metrics.storage.googleapis.com/api/request_count` IS NOT NULL\n| STATS total_r = SUM(`metrics.storage.googleapis.com/api/request_count`),\n        err_r = SUM(`metrics.storage.googleapis.com/api/request_count`) WHERE attributes.response_code != \"OK\"\n    BY entity_id = resource.attributes.bucket_name,\n       t = BUCKET(@timestamp, 40, ?_tstart, ?_tend)\n| EVAL s_err = CASE(total_r > 0, COALESCE(err_r, 0) * 100.0 / total_r, NULL)\n| KEEP entity_id, t, s_err\n| SORT entity_id, t\n| LIMIT 10000"
      }
    },
    {
      "name": "spark_series",
      "source": [
        "spark_raw_traffic"
      ],
      "transform": [
        {
          "type": "filter",
          "expr": "tooltip && tooltip.svc && datum.entity_id === tooltip.svc"
        },
        {
          "type": "filter",
          "expr": "datum.s_err !== null"
        },
        {
          "type": "formula",
          "as": "v",
          "expr": "datum.s_err"
        },
        {
          "type": "collect",
          "sort": {
            "field": "t",
            "order": "ascending"
          }
        }
      ]
    },
    {
      "name": "spark_stat",
      "source": "spark_series",
      "transform": [
        {
          "type": "aggregate",
          "fields": [
            "v",
            "v",
            "v"
          ],
          "ops": [
            "max",
            "mean",
            "valid"
          ],
          "as": [
            "vmax",
            "vavg",
            "vn"
          ]
        }
      ]
    },
    {
      "name": "ranked_svc",
      "source": "raw_all",
      "transform": [
        {
          "type": "formula",
          "as": "sort_key",
          "expr": "datum.svc_pct == null ? 1e12 : -datum.svc_pct * 1000000"
        },
        {
          "type": "collect",
          "sort": {
            "field": [
              "sort_key",
              "svc"
            ],
            "order": [
              "ascending",
              "ascending"
            ]
          }
        },
        {
          "type": "window",
          "ops": [
            "row_number"
          ],
          "as": [
            "active_rank"
          ]
        }
      ]
    },
    {
      "name": "svc_counts",
      "source": "raw_all",
      "transform": [
        {
          "type": "formula",
          "as": "v",
          "expr": "datum.svc_pct"
        },
        {
          "type": "formula",
          "as": "bucket",
          "expr": "datum.v == null ? 3 : (datum.v >= 5 ? 2 : datum.v >= 1 ? 1 : 0)"
        },
        {
          "type": "aggregate",
          "groupby": [
            "bucket"
          ],
          "ops": [
            "count"
          ],
          "as": [
            "count"
          ]
        }
      ]
    },
    {
      "name": "svc_legend_stops",
      "values": [
        {
          "label": "\u2265 5%",
          "val": 5,
          "bucket": 2,
          "is_nodata": false
        },
        {
          "label": "1 \u2013 4%",
          "val": 1,
          "bucket": 1,
          "is_nodata": false
        },
        {
          "label": "< 1%",
          "val": 0,
          "bucket": 0,
          "is_nodata": false
        },
        {
          "label": "Low / no traffic",
          "val": null,
          "bucket": 3,
          "is_nodata": true
        }
      ],
      "transform": [
        {
          "type": "lookup",
          "from": "svc_counts",
          "key": "bucket",
          "fields": [
            "bucket"
          ],
          "values": [
            "count"
          ],
          "as": [
            "count"
          ],
          "default": 0
        },
        {
          "type": "window",
          "ops": [
            "row_number"
          ],
          "as": [
            "idx"
          ]
        }
      ]
    }
  ],
  "signals": [
    {
      "name": "metric",
      "value": "errors",
      "on": [
        {
          "events": "@pill_bg:click",
          "update": "datum.group === 'metric' ? datum.id : metric"
        }
      ]
    },
    {
      "name": "agg",
      "value": "p95"
    },
    {
      "name": "len_raw",
      "update": "length(data('raw_all'))"
    },
    {
      "name": "len_active",
      "update": "length(data('active'))"
    },
    {
      "name": "ts_round",
      "update": "data('ts_probe')[0] ? data('ts_probe')[0].round_key : ''"
    },
    {
      "name": "time_from",
      "update": "ts_round !== '' && indexof(ts_round, '|') > 0 ? slice(ts_round, 0, indexof(ts_round, '|')) : ''"
    },
    {
      "name": "time_to",
      "update": "ts_round !== '' && indexof(ts_round, '|') > 0 ? slice(ts_round, indexof(ts_round, '|') + 1) : ''"
    },
    {
      "name": "g_param",
      "update": "time_from !== '' && time_to !== '' ? '_g=(time:(from:%27' + time_from + '%27,to:%27' + time_to + '%27))&' : ''"
    },
    {
      "name": "raw_round",
      "update": "data('raw_all')[0] ? data('raw_all')[0].round_key : ''"
    },
    {
      "name": "active_round",
      "update": "raw_round"
    },
    {
      "name": "raw_fetched_str",
      "update": "data('raw_all')[0] ? data('raw_all')[0].fetched_at : ''"
    },
    {
      "name": "active_fetched",
      "update": "raw_fetched_str !== '' ? toDate(raw_fetched_str) : 0"
    },
    {
      "name": "tick",
      "value": 0,
      "on": [
        {
          "events": {
            "type": "timer",
            "throttle": 100
          },
          "update": "now()"
        }
      ]
    },
    {
      "name": "url_change_at",
      "value": 0,
      "on": [
        {
          "events": {
            "source": "window",
            "type": "hashchange"
          },
          "update": "now()"
        },
        {
          "events": {
            "source": "window",
            "type": "popstate"
          },
          "update": "now()"
        }
      ]
    },
    {
      "name": "fetch_tracker",
      "init": "{seen: 0, arrived_at: 0}",
      "on": [
        {
          "events": {
            "signal": "tick"
          },
          "update": "active_fetched > 0 && active_fetched !== fetch_tracker.seen ? {seen: active_fetched, arrived_at: tick} : fetch_tracker"
        }
      ]
    },
    {
      "name": "loading_raw",
      "update": "len_active === 0 || ts_round === '' || active_round === '' || active_round !== ts_round || (url_change_at > 0 && fetch_tracker.arrived_at < url_change_at)"
    },
    {
      "name": "loading_started_at",
      "value": 0,
      "on": [
        {
          "events": {
            "signal": "tick"
          },
          "update": "loading_raw ? (loading_started_at === 0 ? tick : loading_started_at) : 0"
        }
      ]
    },
    {
      "name": "loading_elapsed",
      "update": "loading_started_at > 0 ? tick - loading_started_at : 0"
    },
    {
      "name": "no_data",
      "update": "loading_raw && ts_round !== '' && len_raw === 0 && loading_elapsed > 2000"
    },
    {
      "name": "loading",
      "update": "loading_raw && !no_data"
    },
    {
      "name": "loading_timeout",
      "update": "loading && loading_elapsed > 15000"
    },
    {
      "name": "total_instances",
      "update": "len_raw"
    },
    {
      "name": "legendW",
      "value": 150
    },
    {
      "name": "buttonsH",
      "value": 34
    },
    {
      "name": "availW",
      "update": "width - 20 - legendW"
    },
    {
      "name": "availH",
      "update": "height - 20 - buttonsH"
    },
    {
      "name": "hexOffsetY",
      "update": "buttonsH"
    },
    {
      "name": "idealCols",
      "update": "total_instances > 0 && availH > 0 ? max(1, round(sqrt(total_instances * (availW / availH)))) : 1"
    },
    {
      "name": "idealRows",
      "update": "max(1, ceil(total_instances / idealCols))"
    },
    {
      "name": "hexRInitial",
      "update": "min(availW / (idealCols * 2 + 0), availH / (idealRows * 2 + 0))"
    },
    {
      "name": "maxColsAtHexR",
      "update": "max(idealCols, floor(availW / (max(3, hexRInitial) * 2)))"
    },
    {
      "name": "maxColsAtMinR",
      "update": "max(1, floor(availW / (3 * 2)))"
    },
    {
      "name": "gridCols",
      "update": "max(1, min(total_instances, min(maxColsAtHexR, maxColsAtMinR)))"
    },
    {
      "name": "gridRows",
      "update": "max(1, ceil(total_instances / gridCols))"
    },
    {
      "name": "rByWidth",
      "update": "availW / (gridCols * 1.76 + 0.88)"
    },
    {
      "name": "rByHeight",
      "update": "availH / (gridRows * 1.54 + 0.92)"
    },
    {
      "name": "hexR",
      "update": "max(3, min(90, min(rByWidth, rByHeight)))"
    },
    {
      "name": "gapX",
      "update": "hexR * 1.76"
    },
    {
      "name": "gapY",
      "update": "hexR * 1.54"
    },
    {
      "name": "legendX",
      "update": "width - legendW + 4"
    },
    {
      "name": "tooltip",
      "value": {},
      "on": [
        {
          "events": "@hexagons:mouseover",
          "update": "datum"
        },
        {
          "events": "@hexagons:mouseout",
          "update": "{}"
        },
        {
          "events": "@hexagons:click",
          "update": "{}"
        }
      ]
    },
    {
      "name": "selected_instance",
      "value": null,
      "on": [
        {
          "events": "@hexagons:click",
          "update": "{svc: datum.svc, name: datum.svc, loc: datum.loc, proj: datum.proj, x: datum.x, y: datum.y}"
        },
        {
          "events": "@menu_backdrop:click",
          "update": "null"
        },
        {
          "events": "@menu_item_bg:click",
          "update": "null"
        }
      ]
    },
    {
      "name": "menu_x",
      "update": "selected_instance ? (selected_instance.x + 18 + 290 > width - legendW - 10 ? max(selected_instance.x - 18 - 290, 5) : selected_instance.x + 18) : 0"
    },
    {
      "name": "menu_y",
      "update": "selected_instance ? max(5, min(selected_instance.y - 30, height - (108 + menu_hoff) - 6)) : 0"
    },
    {
      "name": "menu_hoff",
      "update": "selected_instance ? (length(selected_instance.name) > 36 ? 14 : 0) : 0"
    },
    {
      "name": "tt_off",
      "update": "tooltip.name ? (length(tooltip.name) <= 36 ? 0 : 14) : 0"
    },
    {
      "name": "tt_h",
      "update": "tooltip.name ? (length(tooltip.name) <= 36 ? 155 : 169) : 155"
    },
    {
      "name": "spark_avg",
      "update": "length(data('spark_stat')) ? data('spark_stat')[0].vavg : null"
    },
    {
      "name": "spark_last",
      "update": "length(data('spark_series')) ? data('spark_series')[length(data('spark_series')) - 1].v : null"
    },
    {
      "name": "spark_delta",
      "update": "(spark_avg != null && spark_avg != 0 && spark_last != null) ? (spark_last - spark_avg) / spark_avg * 100 : null"
    },
    {
      "name": "spark_top",
      "update": "tt_off + 76"
    },
    {
      "name": "spark_bottom",
      "update": "tt_off + 106"
    }
  ],
  "scales": [
    {
      "name": "util_color",
      "type": "threshold",
      "domain": [
        1,
        5
      ],
      "range": [
        "#24C292",
        "#FCD883",
        "#EE4C48"
      ]
    },
    {
      "name": "sparkX",
      "type": "point",
      "range": [
        14,
        276
      ],
      "domain": {
        "data": "spark_series",
        "field": "t"
      }
    },
    {
      "name": "sparkY",
      "type": "linear",
      "nice": false,
      "range": [
        {
          "signal": "spark_bottom"
        },
        {
          "signal": "spark_top"
        }
      ],
      "domain": {
        "signal": "[0, length(data('spark_stat')) && data('spark_stat')[0].vmax > 0 ? data('spark_stat')[0].vmax : 1]"
      }
    }
  ],
  "marks": [
    {
      "type": "text",
      "interactive": false,
      "encode": {
        "update": {
          "x": {
            "value": 5
          },
          "y": {
            "value": 17
          },
          "text": {
            "value": "Color by:"
          },
          "align": {
            "value": "left"
          },
          "baseline": {
            "value": "middle"
          },
          "fontSize": {
            "value": 12
          },
          "fontWeight": {
            "value": 600
          },
          "fill": {
            "value": "#838C99"
          }
        }
      }
    },
    {
      "type": "text",
      "interactive": false,
      "encode": {
        "update": {
          "x": {
            "value": 277
          },
          "y": {
            "value": 17
          },
          "text": {
            "signal": "metric === 'errors' ? 'All non-OK responses \u00b7 coloured once a bucket has 50+ requests' : 'Failures on the Cloud Storage side only \u00b7 50+ requests'"
          },
          "align": {
            "value": "left"
          },
          "baseline": {
            "value": "middle"
          },
          "fontSize": {
            "value": 12
          },
          "fontWeight": {
            "value": 400
          },
          "fill": {
            "signal": "'#838C99'"
          }
        }
      }
    },
    {
      "name": "pill_bg",
      "type": "rect",
      "from": {
        "data": "pills"
      },
      "encode": {
        "enter": {},
        "update": {
          "x": {
            "field": "x"
          },
          "x2": {
            "signal": "datum.x + datum.w"
          },
          "y": {
